from pathlib import Path
import json,sys,wave,hashlib,subprocess
import numpy as np
p=Path(__file__).resolve().parent
spec=json.loads((p/'preregistered-acceptance.json').read_text());assets=json.loads((p/'stock-assets.json').read_text())['assets'];rate=spec['analysis_rate']
def read(path):
 with wave.open(str(path)) as w:
  assert w.getsampwidth()==2 and w.getcomptype()=='NONE';sr=w.getframerate();ch=w.getnchannels();x=np.frombuffer(w.readframes(w.getnframes()),dtype='<i2').astype(float).reshape(-1,ch).mean(axis=1)
 return x,sr,ch
def templates():
 result=[]
 for row in assets:
  path=Path(row['path']);assert hashlib.sha256(path.read_bytes()).hexdigest()==row['sha256'];raw,sr,ch=read(path);assert ch==1
  t=np.interp(np.arange(int(len(raw)*rate/sr))*sr/rate,np.arange(len(raw)),raw);t=(t-t.mean())*row['native_gain'];result.append((row['kind'],path.name,t))
 return result
def match(x,ts):
 n=len(x);prefix=np.r_[0,np.cumsum(x)];squares=np.r_[0,np.cumsum(x*x)];cache={};anchors={}
 for kind,name,t in ts:
  m=len(t);size=1<<(n+m-2).bit_length();dot=np.fft.irfft(np.fft.rfft(x,size)*np.fft.rfft(t[::-1],size),size)[m-1:n];cache[name]=dot
  if kind=='blade':
   energy=squares[m:]-squares[:-m]-(prefix[m:]-prefix[:-m])**2/m;den=np.sqrt(np.maximum(0,energy)*np.dot(t,t));rho=np.divide(dot,den,out=np.zeros_like(dot),where=den>0)
   peaks=np.flatnonzero((rho[1:-1]>=.2)&(rho[1:-1]>=rho[:-2])&(rho[1:-1]>rho[2:]))+1
   candidates=np.unique(np.concatenate([peaks+j for j in range(-2,3)]));candidates=candidates[(candidates>=0)&(candidates<len(dot))];assert len(candidates)<=10000,'excess stock-anchor candidates';anchors[name]=candidates
 ds=np.arange(-spec['maximum_relative_voice_start_samples'],spec['maximum_relative_voice_start_samples']+1);matches=[];rows=[]
 for _,an,a in [v for v in ts if v[0]=='blade']:
  for _,bn,b in [v for v in ts if v[0]=='hand']:
   ea=float(np.dot(a,a));eb=float(np.dot(b,b));m=len(a);k=len(b);fft=1<<(m+k-2).bit_length();cross_all=np.fft.irfft(np.fft.rfft(a,fft)*np.fft.rfft(b[::-1],fft),fft)[:m+k-1];ci=ds+k-1;cross=np.where((ci>=0)&(ci<len(cross_all)),cross_all[np.clip(ci,0,len(cross_all)-1)],0);det=ea*eb-cross*cross
   left=np.minimum(0,ds);length=np.maximum(m,ds+k)-left;template_energy=ea+eb+2*cross;best={'correlation':-1.,'blade':an,'hand':bn};positives=0
   cand=anchors[an]
   for start in range(0,len(cand),64):
    ta=cand[start:start+64,None];tb=ta+ds;begin=ta+left;end=begin+length
    valid=(tb>=0)&(tb<=n-k)&(begin>=0)&(end<=n)&(det>ea*eb*1e-12)
    ca=cache[an][ta];cb=cache[bn][np.clip(tb,0,n-k)];lo=np.clip(begin,0,n);hi=np.clip(end,0,n);window_energy=np.maximum(0,squares[hi]-squares[lo]-(prefix[hi]-prefix[lo])**2/length)
    denominator=np.sqrt(window_energy*template_energy);rho=np.divide(ca+cb,denominator,out=np.full_like(cb,-1.),where=denominator>0)
    ga=(ca*eb-cb*cross)/det;gb=(cb*ea-ca*cross)/det;total=ga+gb;fraction=np.divide(np.minimum(ga,gb),total,out=np.full_like(cb,-1.),where=total>0);valid&=(ga>0)&(gb>0)&(fraction>=spec['minimum_component_gain_fraction']);rho=np.where(valid,rho,-1.)
    idx=np.unravel_index(np.argmax(rho),rho.shape)
    if rho[idx]>best['correlation']:best.update(correlation=float(rho[idx]),offset_seconds=float(begin[idx]/rate),relative_voice_samples=int(ds[idx[1]]),blade_gain=float(ga[idx]),hand_gain=float(gb[idx]))
    passed=np.argwhere(rho>=spec['minimum_normalized_stock_mixture_correlation']);positives+=len(passed)
    for i,j in passed:matches.append((float(begin[i,j]/rate),float(rho[i,j]),an,bn))
   best['positive_candidate_windows']=positives;rows.append(best)
 clusters=[]
 for time,corr,a,b in sorted(matches):
  if not clusters or time-clusters[-1]['last']>1:clusters.append({'first':time,'last':time,'maximum_correlation':corr,'blade':a,'hand':b})
  else:
   clusters[-1]['last']=time
   if corr>clusters[-1]['maximum_correlation']:clusters[-1].update(maximum_correlation=corr,blade=a,hand=b)
 return {'clusters':clusters,'pairs':rows,'analysis_rate':rate,'minimum_correlation':spec['minimum_normalized_stock_mixture_correlation'],'minimum_component_gain_fraction':spec['minimum_component_gain_fraction'],'method':spec['audio_method']}
if __name__=='__main__':
 phase=sys.argv[1];expected=int(sys.argv[2]);folder=p/phase;source=folder/'mixed-output.wav';rendered=folder/'rendered-audio.wav'
 subprocess.run(['ffmpeg','-v','error','-y','-i',str(source),'-ar','48000','-ac','2','-acodec','pcm_s16le',str(rendered)],check=True)
 raw,sr,ch=read(rendered);assert (sr,ch)==(48000,2);x=raw[::4];result=match(x,templates());result.update(passed=len(result['clusters'])==expected,expected_clusters=expected,mixed_pcm_sha256=hashlib.sha256(source.read_bytes()).hexdigest(),rendered_pcm_sha256=hashlib.sha256(rendered.read_bytes()).hexdigest(),scope='Weighted stock Blade+Hand PCM mixture with positive fitted gains for both components; actual captured mixer output. This is not isolated hardware listening or native pitch/reverb equivalence.')
 out=folder/f'audio-mixture-verification-{expected}.json';out.write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result,indent=2));assert result['passed']

